<?php
declare(strict_types=1);
require_once __DIR__.'/finance_core.php';require_once __DIR__.'/invoice_lib.php';require_once __DIR__.'/invoice_archive.php';
function businessCopy(PDO $pdo,array $old,string $kind,?int $source,string $status='draft',?string $number=null,?string $date=null,int $sign=1,?string $noteOverride=null):int {
 $columns=['customer_id','property_id','recipient_name','recipient_address','recipient_email','issuer_name','issuer_address','issuer_tax_id','issuer_vat_id','issuer_iban','issuer_bic','issuer_bank','currency'];$values=[];foreach($columns as $c)$values[]=$old[$c];$columns=[...$columns,'document_kind','source_document_id','status','number','invoice_date','service_date','due_date','notes','net_total','tax_total','gross_total'];$values=[...$values,$kind,$source,$status,$number,$date,$old['service_date'],$date===null?null:$old['due_date'],$noteOverride??($kind==='credit_note'?'Storno/Korrektur zu '.$old['number'].'. Keine Bankaktion.':'Aus Angebot '.$old['number']),financeDecimal($sign*financeCents($old['net_total'])),financeDecimal($sign*financeCents($old['tax_total'])),financeDecimal($sign*financeCents($old['gross_total']))];$pdo->prepare('INSERT INTO invoices('.implode(',',$columns).') VALUES('.implode(',',array_fill(0,count($columns),'?')).')')->execute($values);$id=(int)$pdo->lastInsertId();
 foreach(invItems($pdo,(int)$old['id']) as $item)$pdo->prepare('INSERT INTO invoice_items(invoice_id,position,description,quantity,unit,unit_price,tax_rate,net_amount,tax_amount,gross_amount) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$id,$item['position'],$item['description'],$item['quantity'],$item['unit'],($sign<0?(str_starts_with($item['unit_price'],'-')?substr($item['unit_price'],1):'-'.$item['unit_price']):$item['unit_price']),$item['tax_rate'],financeDecimal($sign*financeCents($item['net_amount'])),financeDecimal($sign*financeCents($item['tax_amount'])),financeDecimal($sign*financeCents($item['gross_amount']))]);return $id;
}
function offerCreate(PDO $pdo,int $admin,array $input,array $config):int {
 $customer=(int)($input['customer_id']??0);$q=$pdo->prepare('SELECT * FROM customers WHERE id=?');$q->execute([$customer]);$c=$q->fetch();if(!$c)throw new InvalidArgumentException('Kunde erforderlich.');if(!empty($c['archived_at']))throw new RuntimeException('Archivierten Kunden zuerst reaktivieren.');$address=trim((string)($input['recipient_address']??''));if($address==='')$address=trim((string)($c['billing_address']??''));if($address===''||mb_strlen($address)>2000||empty($config['invoice_issuer_name'])||empty($config['invoice_issuer_address']))throw new InvalidArgumentException('Empfänger-/Ausstelleranschrift erforderlich.');$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO invoices(customer_id,recipient_name,recipient_address,recipient_email,issuer_name,issuer_address,issuer_tax_id,issuer_vat_id,issuer_iban,issuer_bic,issuer_bank,document_kind) VALUES(?,?,?,?,?,?,?,?,?,?,?,'offer')")->execute([$customer,$c['name'],$address,$c['email'],$config['invoice_issuer_name'],$config['invoice_issuer_address'],$config['invoice_tax_id'],$config['invoice_vat_id'],$config['invoice_iban'],$config['invoice_bic'],$config['invoice_bank']]);$id=(int)$pdo->lastInsertId();gszAudit($pdo,$admin,'offer_created',['offer_id'=>$id]);$pdo->commit();return $id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function offerItem(PDO $pdo,int $admin,int $id,array $input):void {
 $text=trim((string)($input['description']??''));$qty=invDecimal((string)($input['quantity']??''));$price=invMoney((string)($input['unit_price']??''));$rate=filter_var($input['tax_rate']??'',FILTER_VALIDATE_INT);if($text===''||mb_strlen($text)>500||$qty<1||!in_array($rate,[0,7,19],true))throw new InvalidArgumentException('Angebotsposition ungültig.');if($price>0&&$qty>intdiv(PHP_INT_MAX-500,$price))throw new InvalidArgumentException('Positionsbetrag zu groß.');$net=intdiv($qty*$price+500,1000);$tax=intdiv($net*$rate+50,100);$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT id FROM invoices WHERE id=? AND document_kind='offer' AND status='draft' FOR UPDATE");$q->execute([$id]);if(!$q->fetchColumn())throw new RuntimeException('Nur Angebotsentwurf bearbeitbar.');$q=$pdo->prepare('SELECT COALESCE(MAX(position),0)+1 FROM invoice_items WHERE invoice_id=?');$q->execute([$id]);$position=(int)$q->fetchColumn();$pdo->prepare("INSERT INTO invoice_items(invoice_id,position,description,quantity,unit,unit_price,tax_rate,net_amount,tax_amount,gross_amount) VALUES(?,?,?,?,'Stk',?,?,?,?,?)")->execute([$id,$position,$text,number_format($qty/1000,3,'.',''),financeDecimal($price),$rate,financeDecimal($net),financeDecimal($tax),financeDecimal($net+$tax)]);invRecalc($pdo,$id);gszAudit($pdo,$admin,'offer_item',['offer_id'=>$id]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function offerIssue(PDO $pdo,int $admin,int $id,string $date):void {
 if(!zgsValidDate($date))throw new InvalidArgumentException('Datum ungültig.');$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT * FROM invoices WHERE id=? AND document_kind='offer' FOR UPDATE");$q->execute([$id]);$offer=$q->fetch();if(!$offer)throw new RuntimeException('Angebot fehlt.');if($offer['status']==='issued'){$pdo->commit();return;}if($offer['status']!=='draft'||!invItems($pdo,$id))throw new RuntimeException('Angebot benötigt Entwurf und Positionen.');$year=(int)substr($date,0,4);$pdo->prepare('INSERT INTO offer_sequences(year,last_number) VALUES(?,0) ON DUPLICATE KEY UPDATE year=VALUES(year)')->execute([$year]);$q=$pdo->prepare('SELECT last_number FROM offer_sequences WHERE year=? FOR UPDATE');$q->execute([$year]);$next=(int)$q->fetchColumn()+1;$pdo->prepare('UPDATE offer_sequences SET last_number=? WHERE year=?')->execute([$next,$year]);$pdo->prepare("UPDATE invoices SET number=?,status='issued',invoice_date=?,issued_at=UTC_TIMESTAMP() WHERE id=?")->execute([sprintf('ANG-%04d-%05d',$year,$next),$date,$id]);invoiceArchive($pdo,$id);gszAudit($pdo,$admin,'offer_issued',['offer_id'=>$id]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function offerConvert(PDO $pdo,int $admin,int $id):int {
 $pdo->beginTransaction();try{$q=$pdo->prepare("SELECT * FROM invoices WHERE id=? AND document_kind='offer' FOR UPDATE");$q->execute([$id]);$old=$q->fetch();if(!$old||$old['status']!=='issued')throw new RuntimeException('Freigegebenes Angebot erforderlich.');$q=$pdo->prepare("SELECT id FROM invoices WHERE source_document_id=? AND document_kind='invoice'");$q->execute([$id]);if($new=$q->fetchColumn()){$pdo->commit();return (int)$new;}$new=businessCopy($pdo,$old,'invoice',$id);invEvent($pdo,$new,'created_from_offer','Angebot #'.$id);gszAudit($pdo,$admin,'offer_converted',['offer_id'=>$id,'invoice_id'=>$new]);$pdo->commit();return $new;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function invoiceCredit(PDO $pdo,int $admin,int $id,string $date,string $reason):int {
 if(!zgsValidDate($date)||trim($reason)===''||mb_strlen($reason)>500)throw new InvalidArgumentException('Stornodatum und Begründung erforderlich.');$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT * FROM invoices WHERE id=? AND document_kind='invoice' FOR UPDATE");$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('Ursprungsrechnung fehlt.');if($old['correction_document_id']){$pdo->commit();return (int)$old['correction_document_id'];}if($date<$old['invoice_date'])throw new RuntimeException('Stornodatum liegt vor Ursprungsrechnung.');if(!in_array($old['status'],['issued','paid'],true))throw new RuntimeException('Ausgestellte Rechnung erforderlich.');$year=(int)substr($date,0,4);$pdo->prepare('INSERT INTO invoice_sequences(year,last_number) VALUES(?,0) ON DUPLICATE KEY UPDATE year=VALUES(year)')->execute([$year]);$q=$pdo->prepare('SELECT last_number FROM invoice_sequences WHERE year=? FOR UPDATE');$q->execute([$year]);$next=(int)$q->fetchColumn()+1;$pdo->prepare('UPDATE invoice_sequences SET last_number=? WHERE year=?')->execute([$next,$year]);$new=businessCopy($pdo,$old,'credit_note',$id,'issued',sprintf('GSZ-%04d-%05d',$year,$next),$date,-1);$pdo->prepare('UPDATE invoices SET notes=CONCAT(notes,?) WHERE id=?')->execute(["\nGrund: ".$reason,$new]);$credit=invGet($pdo,$new);invoiceArchive($pdo,$new);$pdo->prepare("UPDATE invoices SET status='cancelled',cancelled_at=UTC_TIMESTAMP(),correction_document_id=? WHERE id=?")->execute([$new,$id]);invEvent($pdo,$id,'credit_note_created','Stornobeleg #'.$new);invEvent($pdo,$new,'issued','Referenz Ursprungsrechnung #'.$id);gszAudit($pdo,$admin,'invoice_credit_note',['invoice_id'=>$id,'credit_id'=>$new]);$pdo->commit();return $new;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
